// Package service installs and controls the agent as a native system service:
// systemd or OpenRC on Linux, rc.d on FreeBSD, the Service Control Manager on
// Windows. Service definitions are generated by pure functions (unit-tested);
// installation uses only the platform's own tools.
package service

import (
	"fmt"
	"strings"
)

const (
	Name        = "osriva-agent"
	DisplayName = "OSRIVA Agent"
	Description = "OSRIVA Panel agent: reports this server's inventory to the control plane"
)

// shellQuote quotes a value for /bin/sh.
func shellQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }

// systemdQuote quotes a value for a systemd ExecStart line.
func systemdQuote(s string) string {
	return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`, `%`, `%%`, `$`, `$$`).Replace(s) + `"`
}

// SystemdUnit returns the systemd unit. The agent runs as root because server
// management (Phase 3) needs it; the unit still applies conservative hardening.
func SystemdUnit(bin, configDir string) string {
	return fmt.Sprintf(`[Unit]
Description=%s
Documentation=https://github.com/mdreayadpramanik/osriva-panel
Wants=network-online.target
After=network-online.target

[Service]
Type=simple
ExecStart=%s run --config-dir %s
Restart=on-failure
RestartSec=10s
# Exit code 3 means the control plane revoked this agent: do not restart.
RestartPreventExitStatus=3
NoNewPrivileges=yes
PrivateTmp=yes
ProtectHome=read-only
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictSUIDSGID=yes
LockPersonality=yes
UMask=0077

[Install]
WantedBy=multi-user.target
`, Description, systemdQuote(bin), systemdQuote(configDir))
}

// OpenRCScript returns an OpenRC init script using supervise-daemon.
func OpenRCScript(bin, configDir string) string {
	return fmt.Sprintf(`#!/sbin/openrc-run
description=%s
supervisor=supervise-daemon
command=%s
command_args="run --config-dir %s"
respawn_delay=10
output_log="/var/log/osriva-agent.log"
error_log="/var/log/osriva-agent.log"

depend() {
	need net
	after firewall
}
`, shellQuote(Description), shellQuote(bin), shellQuote(configDir))
}

// FreeBSDRCScript returns an rc.d script that runs the agent under daemon(8).
func FreeBSDRCScript(bin, configDir string) string {
	return fmt.Sprintf(`#!/bin/sh
#
# PROVIDE: osriva_agent
# REQUIRE: NETWORKING
# KEYWORD: shutdown

. /etc/rc.subr

name="osriva_agent"
rcvar="osriva_agent_enable"
load_rc_config $name
: ${osriva_agent_enable:="NO"}

pidfile="/var/run/${name}.pid"
procname=%s
command="/usr/sbin/daemon"
command_args="-r -R 10 -P ${pidfile} -o /var/log/osriva-agent.log %s run --config-dir %s"

run_rc_command "$1"
`, shellQuote(bin), shellQuote(bin), shellQuote(configDir))
}

// WindowsArgs are the arguments the Windows service starts the agent with.
func WindowsArgs(configDir string) []string {
	return []string{"run", "--config-dir", configDir}
}
